/// A seatLease, from rust/sim/schema/seats.mjs, rust/sim/schema/units.mjs, rust/sim/schema/vehicles.mjs.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct SeatLease {
    pub unit: Option<Ref<Unit>>,
    pub generation: f64,
    pub human: bool,
    pub team: f64,
    pub vehicle: Option<Ref<Vehicle>>,
    pub turret: Option<Ref<Turret>>,
    pub index: f64,
    pub role: SeatRole,
    pub since: f64,
    pub tick: f64,
    pub was: [f64; 2],
    pub exit_request: Option<ExitRequest>,
    pub released: bool,
    pub input: SeatInput,
    pub controllable: Option<Ref<SeatUnit>>,
}

impl SeatLease {
    /// Words a row takes: slot, generation, then the fields mirrored (export),
    /// read by a Rust phase while JavaScript owns the kind (import), or all (full).
    pub const EXPORT_STRIDE: usize = 54;
    pub const IMPORT_STRIDE: usize = 54;
    pub const FULL_STRIDE: usize = 54;

    pub fn put_full(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 54] = (&mut row[..54]).try_into().unwrap();
        match &self.unit { Some(v) => { row[2] = 0.0; row[2 + 1] = (*v).slot as f64; row[2 + 1 + 1] = (*v).gen as f64; } None => { row[2] = 1.0; row[2 + 1..2 + 3].fill(0.0); } }
        row[5] = self.generation;
        row[6] = if self.human { 1.0 } else { 0.0 };
        row[7] = self.team;
        match &self.vehicle { Some(v) => { row[8] = 0.0; row[8 + 1] = (*v).slot as f64; row[8 + 1 + 1] = (*v).gen as f64; } None => { row[8] = 1.0; row[8 + 1..8 + 3].fill(0.0); } }
        match &self.turret { Some(v) => { row[11] = 0.0; row[11 + 1] = (*v).slot as f64; row[11 + 1 + 1] = (*v).gen as f64; } None => { row[11] = 1.0; row[11 + 1..11 + 3].fill(0.0); } }
        row[14] = self.index;
        row[15] = self.role as u8 as f64;
        row[16] = self.since;
        row[17] = self.tick;
        row[18..18 + 2].copy_from_slice(&self.was);
        match &self.exit_request { Some(v) => { row[20] = 0.0; v.put(&mut row[20 + 1..], heap); } None => { row[20] = 1.0; row[20 + 1..20 + 7].fill(0.0); } }
        row[27] = if self.released { 1.0 } else { 0.0 };
        self.input.put(&mut row[28..], heap);
        match &self.controllable { Some(v) => { row[51] = 0.0; row[51 + 1] = (*v).slot as f64; row[51 + 1 + 1] = (*v).gen as f64; } None => { row[51] = 1.0; row[51 + 1..51 + 3].fill(0.0); } }
    }

    pub fn take_full(&mut self, row: &[f64], heap: &[f64]) {
        let row: &[f64; 54] = (&row[..54]).try_into().unwrap();
        self.unit = if row[2] == 0.0 { Some(Ref::new(word_u32(row[2 + 1]), word_u32(row[2 + 1 + 1]))) } else { None };
        self.generation = row[5];
        self.human = row[6] != 0.0;
        self.team = row[7];
        self.vehicle = if row[8] == 0.0 { Some(Ref::new(word_u32(row[8 + 1]), word_u32(row[8 + 1 + 1]))) } else { None };
        self.turret = if row[11] == 0.0 { Some(Ref::new(word_u32(row[11 + 1]), word_u32(row[11 + 1 + 1]))) } else { None };
        self.index = row[14];
        self.role = SeatRole::from_u8(word_u32(row[15]) as u8).unwrap_or_default();
        self.since = row[16];
        self.tick = row[17];
        self.was = { let mut a = [0.0; 2]; a.copy_from_slice(&row[18..18 + 2]); a };
        self.exit_request = if row[20] == 0.0 { Some(ExitRequest::take(&row[20 + 1..], heap)) } else { None };
        self.released = row[27] != 0.0;
        self.input = SeatInput::take(&row[28..], heap);
        self.controllable = if row[51] == 0.0 { Some(Ref::new(word_u32(row[51 + 1]), word_u32(row[51 + 1 + 1]))) } else { None };
    }

    #[inline(always)]
    pub fn put_export(&self, row: &mut [f64], heap: &mut Vec<f64>) { self.put_full(row, heap) }

    #[inline(always)]
    pub fn take_export(&mut self, row: &[f64], heap: &[f64]) { self.take_full(row, heap) }

    #[inline(always)]
    pub fn put_import(&self, row: &mut [f64], heap: &mut Vec<f64>) { self.put_full(row, heap) }

    #[inline(always)]
    pub fn take_import(&mut self, row: &[f64], heap: &[f64]) { self.take_full(row, heap) }

}

